    #[test]
    fn dzmz_optimizer_discounts_the_first_program_installed_each_turn_but_not_hardware() {
        let registry = sg_registry();
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.rig = vec![rig_card_with_counters("dzmz_optimizer", 0)];
        state.runner.grip = vec![CardId("corroder".to_string()), CardId("gordian_blade".to_string())];

        let (state, _) = apply_action(
            &state,
            &registry,
            PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false },
        )
        .expect("install corroder");
        assert_eq!(state.runner.resources.credits, Credits(9), "10 - 2 (cost) + 1 (DZMZ discount)");
        assert!(state.runner.once_per_turn_used.is_empty(), "read off the turn: nothing on the card is spent");

        let (state, _) = apply_action(
            &state,
            &registry,
            PlayerAction::InstallProgram { card_id: CardId("gordian_blade".to_string()), trash_first: false },
        )
        .expect("install gordian blade");
        assert_eq!(state.runner.resources.credits, Credits(5), "9 - 4 (cost), discount already used this turn");

        // Two copies are two abilities, each with its own first time: the
        // first program costs 2 less and the second pays in full. The
        // `first_install_discount` field returned the first source it found
        // and spent one flag for everyone, so the second copy did nothing —
        // in the nine sample decks that play two.
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.rig = vec![rig_card_with_counters("dzmz_optimizer", 0), rig_card_with_counters("dzmz_optimizer", 0)];
        state.runner.rig[1].install_id = crate::rules::InstallId(state.runner.rig[0].install_id.0 + 1);
        state.runner.grip = vec![CardId("corroder".to_string()), CardId("gordian_blade".to_string())];
        let (state, _) =
            apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false }).expect("install corroder");
        assert_eq!(state.runner.resources.credits, Credits(10), "2 (cost) - 1 - 1");
        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("gordian_blade".to_string()), trash_first: false })
            .expect("install gordian blade");
        assert_eq!(state.runner.resources.credits, Credits(6), "both first times are spent");
    }

    /// The report this item closes on. "The first program you install each
    /// turn" is a fact about the turn, and an Optimizer that arrives after
    /// that program has missed it. While the discount was a once-per-turn
    /// use of the *card*, a copy installed mid-turn still had its use and
    /// lowered the turn's second program.
    #[test]
    fn a_dzmz_optimizer_installed_after_the_turns_first_program_discounts_nothing_until_next_turn() {
        let registry = sg_registry();
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.grip = vec![CardId("corroder".to_string()), CardId("dzmz_optimizer".to_string()), CardId("gordian_blade".to_string()), CardId("corroder".to_string())];

        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false }).expect("the turn's first program");
        assert_eq!(state.runner.resources.credits, Credits(8), "10 - 2");
        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallHardware { card_id: CardId("dzmz_optimizer".to_string()) }).expect("install the optimizer");
        assert_eq!(state.runner.resources.credits, Credits(6), "8 - 2");
        let (mut state, _) = apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("gordian_blade".to_string()), trash_first: false }).expect("the turn's second program");
        assert_eq!(state.runner.resources.credits, Credits(2), "6 - 4: not the first program this turn, whoever was watching the first");

        crate::rules::turn_log::rotate(&mut state);
        state.runner.resources.clicks = Clicks(4);
        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false }).expect("next turn's first program");
        assert_eq!(state.runner.resources.credits, Credits(1), "2 - 2 + 1");
    }

    /// The same sentence on a trigger: a Verbal Plasticity installed after
    /// the turn's first basic draw has missed it.
    #[test]
    fn a_verbal_plasticity_installed_after_the_turns_first_draw_draws_nothing_extra() {
        let registry = sg_registry();
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.grip = vec![CardId("verbal_plasticity".to_string())];
        state.runner.stack = (0..4).map(|i| CardId(format!("stack_card_{i}"))).collect();

        let (state, _) = apply_action(&state, &registry, PlayerAction::DrawCardClick { side: Side::Runner }).expect("the turn's first draw");
        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallResource { card_id: CardId("verbal_plasticity".to_string()), host: None }).expect("install");
        let held = state.runner.grip.len();
        let (state, _) = apply_action(&state, &registry, PlayerAction::DrawCardClick { side: Side::Runner }).expect("the turn's second draw");
        assert_eq!(state.runner.grip.len(), held + 1, "one card: this was not the turn's first draw");
    }

    /// Kate had no test: her discount was a field only an identity could
    /// carry. It reaches hardware as well as programs, never a resource, and
    /// stacks with a DZMZ Optimizer's — the field returned hers alone.
    #[test]
    fn kate_lowers_the_first_program_or_hardware_each_turn_and_stacks_with_dzmz_optimizer() {
        let registry = sg_registry();
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.identity = Some(CardId("kate_mac_mccaffrey_digital_tinker".to_string()));
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.grip =
            vec![CardId("telework_contract".to_string()), CardId("dzmz_optimizer".to_string()), CardId("corroder".to_string())];

        let (state, _) = apply_action(&state, &registry, PlayerAction::InstallResource { card_id: CardId("telework_contract".to_string()), host: None })
            .expect("install telework contract");
        assert_eq!(state.runner.resources.credits, Credits(9), "a resource pays its printed 1, and spends nobody's first time");
        let (mut state, _) = apply_action(&state, &registry, PlayerAction::InstallHardware { card_id: CardId("dzmz_optimizer".to_string()) })
            .expect("install dzmz optimizer");
        assert_eq!(state.runner.resources.credits, Credits(8), "9 - 2 (cost) + 1 (Kate)");
        let (after, _) =
            apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false }).expect("install corroder");
        assert_eq!(after.runner.resources.credits, Credits(7), "8 - 2 (cost) + 1 (DZMZ); Kate's is spent");

        // A new turn: both apply to the one install. DZMZ's is a use that
        // is cleared; Kate's is read off the turn, which starts empty.
        state.runner.once_per_turn_used.clear();
        crate::rules::turn_log::rotate(&mut state);
        let (state, _) =
            apply_action(&state, &registry, PlayerAction::InstallProgram { card_id: CardId("corroder".to_string()), trash_first: false }).expect("install corroder");
        assert_eq!(state.runner.resources.credits, Credits(8), "8 - 2 (cost) + 1 (Kate) + 1 (DZMZ)");
    }

    #[test]
    fn t400_memory_diamond_grants_memory_and_max_hand_size_for_as_long_as_it_is_installed() {
        let registry = sg_registry();
        let mut state = base_state();
        state.phase = GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.runner.resources.credits = Credits(10);
        state.runner.memory_units = crate::rules::MemoryUnits(4);
        state.runner.grip = vec![CardId("t400_memory_diamond".to_string())];
        state.runner.grip.extend((0..6).map(|i| CardId(format!("filler_{i}"))));

        let (state, _) = apply_action(
            &state,
            &registry,
            PlayerAction::InstallHardware { card_id: CardId("t400_memory_diamond".to_string()) },
        )
        .expect("install t400 memory diamond");

        assert_eq!(state.runner.memory_units, crate::rules::MemoryUnits(5));
        assert_eq!(state.runner.grip.len(), 6, "t400 itself left the grip on install, 6 filler cards remain");

        // 6 cards exceeds the base limit of 5 but exactly fits 5 + 1.
        assert_eq!(discards_owed_at_end_of_turn(&state, &registry), 0, "6 cards fit under 5 + 1");

        // The +1 is the card's for as long as it is installed. It used to be
        // folded into the state at install and never taken out, so a T400
        // the Corp trashed (Retribution) went on paying: five games of the
        // 768 in a 256-seed sweep.
        let mut trashed = state.clone();
        let t400 = trashed.runner.rig.remove(0);
        trashed.runner.heap.push(t400.card);
        assert_eq!(discards_owed_at_end_of_turn(&trashed, &registry), 1, "the limit went with the card");
    }

