    #[test]
    fn the_zwicky_group_draws_once_a_turn_when_an_agenda_or_operation_pays_out() {
        let registry = sg_registry();
        let mut state = base_state();
        state.corp.identity = Some(CardId("the_zwicky_group_invisible_hands".to_string()));
        state.corp.hq = vec![CardId("hedge_fund".to_string()), CardId("hedge_fund".to_string())];
        state.corp.r_and_d = vec![CardId("ice_wall".to_string()); 4];

        let (played, _) = apply_action(&state, &registry, PlayerAction::PlayOperation { card_id: CardId("hedge_fund".to_string()) }).expect("play");
        // "You may draw 1 card": asked, not forced.
        assert!(matches!(played.pending_decision, Some(crate::rules::PendingDecision::ChooseEffect { chooser: Side::Corp, .. })), "the Corp is asked");
        let (declined, _) = apply_action(&played, &registry, PlayerAction::ResolvePendingChoice { option_index: 1 }).expect("decline");
        assert_eq!(declined.corp.hq.len(), 1, "declined: only the other Hedge Fund");
        let (state, _) = apply_action(&played, &registry, PlayerAction::ResolvePendingChoice { option_index: 0 }).expect("draw");
        assert_eq!(state.corp.hq.len(), 2, "one Hedge Fund left, plus the card it drew");
        // Once per turn: the second operation pays out but asks nothing.
        let (state, _) = apply_action(&state, &registry, PlayerAction::PlayOperation { card_id: CardId("hedge_fund".to_string()) }).expect("play again");
        assert!(state.pending_decision.is_none());
        assert_eq!(state.corp.hq.len(), 1, "no second draw");
        // Declining was the first time too: the turn's second payout asks nothing.
        let (declined, _) = apply_action(&declined, &registry, PlayerAction::PlayOperation { card_id: CardId("hedge_fund".to_string()) }).expect("play again");
        assert!(declined.pending_decision.is_none(), "the first time each turn was the declined one");

        // An asset's credits are not an agenda's or an operation's.
        let mut state = base_state();
        state.corp.identity = Some(CardId("the_zwicky_group_invisible_hands".to_string()));
        state.corp.r_and_d = vec![CardId("ice_wall".to_string()); 4];
        state.corp.installed = vec![installed_with_counters("regolith_mining_license", ServerId::Remote(0), 15)];
        let (state, _) = apply_action(&state, &registry, PlayerAction::ActivateAbility { target: install_of(&state, "regolith_mining_license"), ability_index: 0 }).expect("mine");
        assert_eq!(state.corp.resources.credits, Credits(13));
        assert!(state.corp.hq.is_empty(), "an asset does not trigger it");
    }

    #[test]
    fn greenmail_pays_two_when_scored_and_four_more_when_forfeited() {
        let registry = sg_registry();
        let mut state = base_state();
        state.corp.resources.credits = Credits(0);
        state.corp.installed = vec![corp_root("greenmail", ServerId::Remote(0))];
        state.corp.installed[0].rezzed = false;
        state.corp.installed[0].advancement_tokens = 2;

        let (state, _) = apply_action(&state, &registry, PlayerAction::ScoreAgenda { target: install_of(&state, "greenmail") }).expect("score");
        assert_eq!(state.corp.resources.credits, Credits(2), "2 on score");

        // Forfeited through Biawak's rez: 4 more, and the agenda leaves the game.
        let mut state = runner_turn(5, 4);
        state.corp.resources.credits = Credits(4);
        state.corp.scored_agendas = vec![crate::rules::ScoredAgenda::plain(CardId("greenmail".to_string()))];
        let greenmail_points = registry.get(&CardId("greenmail".to_string())).and_then(|c| c.agenda_points).expect("an agenda");
        state.corp.resources.agenda_points = crate::rules::AgendaPoints(greenmail_points as i32);
        state.corp.installed = vec![ice_installed("biawak", ServerId::Hq, false)];
        let (state, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Hq }).expect("run");
        let (state, _) = crate::rules::test_support::continue_run(&state, &registry).expect("approach");
        let (state, events) = apply_action(&state, &registry, PlayerAction::RezIce { ice: install_of(&state, "biawak") }).expect("forfeit and rez");
        assert!(state.corp.installed[0].rezzed);
        assert!(state.corp.scored_agendas.is_empty());
        assert_eq!(state.corp.resources.credits, Credits(4), "4 paid for the rez, 4 back from Greenmail");
        // CR 1.17.1: the score is the score area's, so the forfeit took
        // Greenmail's points with it. The shown score used to keep them.
        assert_eq!(state.corp.resources.agenda_points.0, 0);
        assert!(events.iter().any(|e| matches!(e, crate::rules::GameEvent::AgendaForfeited { .. })));
    }

    #[test]
    fn plutus_is_rezzed_by_forfeiting_or_trashing_three_and_replays_a_transaction_from_archives() {
        let registry = sg_registry();
        let plutus = |state: &GameState| PlayerAction::RezIce { ice: install_of(state, "plutus") };
        let mut base = base_state();
        base.corp.installed = vec![corp_root("plutus", ServerId::Remote(0))];
        base.corp.installed[0].rezzed = false;

        // Neither cost is payable: the rez is refused outright, and never offered.
        let bare = base.clone();
        let err = apply_action(&bare, &registry, plutus(&bare)).expect_err("nothing to pay with");
        assert!(matches!(err, RulesError::NoAvailableRezAlternative { .. }), "{err:?}");
        assert!(!crate::rules::legal_actions(&bare, &registry).contains(&plutus(&bare)));

        // Three cards in HQ is one way, and the only one here.
        let mut hq = base.clone();
        hq.corp.hq = vec![CardId("hedge_fund".to_string()), CardId("ice_wall".to_string()), CardId("enigma".to_string())];
        let (hq, _) = apply_action(&hq, &registry, plutus(&hq)).expect("trash three");
        // Exactly three cards for a cost of three: nothing to ask, and the
        // cards are revealed, so they land faceup.
        assert!(hq.pending_payment.is_none() && hq.pending_decision.is_none());
        assert!(hq.corp.hq.is_empty());
        assert!(hq.corp.archives.iter().all(|a| !a.facedown), "revealed as they were trashed");
        assert!(hq.corp.installed[0].rezzed, "the rez follows the payment");

        // With an agenda too, the Corp picks which cost to pay.
        let mut both = base.clone();
        both.corp.hq = vec![CardId("hedge_fund".to_string()); 3];
        both.corp.scored_agendas = vec![crate::rules::ScoredAgenda::plain(CardId("offworld_office".to_string()))];
        let (both, _) = apply_action(&both, &registry, plutus(&both)).expect("two ways to pay");
        assert!(matches!(&both.pending_payment, Some(crate::rules::PendingPayment { question: crate::rules::PaymentAsk::Alternative { .. }, .. })));
        let (forfeited, _) = apply_action(&both, &registry, PlayerAction::ResolvePendingChoice { option_index: 0 }).expect("forfeit instead");
        assert!(forfeited.corp.scored_agendas.is_empty());
        assert_eq!(forfeited.corp.hq.len(), 3, "HQ untouched");
        assert!(forfeited.corp.installed[0].rezzed);

        // Its turn-start ability replays a transaction out of Archives and
        // removes it from the game.
        let mut state = base_state();
        state.corp.resources.credits = Credits(5);
        state.corp.r_and_d = vec![CardId("ice_wall".to_string()); 3];
        state.corp.installed = vec![corp_root("plutus", ServerId::Remote(0))];
        state.corp.archives = vec![
            ArchivedCard::faceup(CardId("hedge_fund".to_string())),
            ArchivedCard::faceup(CardId("seamless_launch".to_string())),
        ];
        let (state, _) = apply_action(&crate::rules::test_support::clicks_spent(&state), &registry, PlayerAction::EndTurn).expect("end turn");
        let (state, _) = pass_until_settled(state, &registry);
        let (state, _) = apply_action(&crate::rules::test_support::clicks_spent(&state), &registry, PlayerAction::EndTurn).expect("runner ends");
        let state = advance_until_choice(state, &registry);
        assert!(matches!(state.pending_decision, Some(crate::rules::PendingDecision::ChooseCards { side: Side::Corp, .. })), "offered a transaction");
        assert!(apply_action(&state, &registry, PlayerAction::ToggleCardSelection { position: position_of(&state, "seamless_launch") }).is_err(), "not a transaction");
        let (state, _) = apply_action(&state, &registry, PlayerAction::ToggleCardSelection { position: position_of(&state, "hedge_fund") }).expect("pick it");
        let (state, _) = apply_action(&state, &registry, PlayerAction::ConfirmCardSelection).expect("play it");
        assert_eq!(state.corp.resources.credits, Credits(9), "5 - 5 + 9");
        assert!(state.corp.removed_from_game.contains(&CardId("hedge_fund".to_string())), "gone after it resolves");
        assert!(!state.corp.archives.iter().any(|a| a.card.0 == "hedge_fund"));
    }

    /// The diagnosis test for the prompt livelock (ROADMAP Phase 2 §5).
    ///
    /// Self-play games were parking in `ChooseCards` prompts with `min ==
    /// max` over HQ — Plutus's alternative rez cost (3 of 5), Anoetic Void's
    /// paid choice (2 of 5), Sprint's on-play (2 of 7) — and toggling for
    /// ~9,700 actions with `ConfirmCardSelection` legal in only 6–8% of
    /// them. Two explanations fit that number and need different fixes: a
    /// chooser that never settles on a full selection, or a Confirm that is
    /// silently *withheld* at a valid count because its resolution fails
    /// (`legal_actions` keeps an action only if the whole `apply_action`
    /// succeeds — the shape `CardFilter::UnrezzedIce` once produced). The
    /// per-card tests above only ever confirm the minimal HQ where every
    /// card is selected; the livelock shape is a proper subset of a mixed
    /// hand, where the cards actually moved differ by selection. So this
    /// walks **every** `min`-subset of a realistic HQ and demands Confirm is
    /// offered and resolves for each — a failure names the subset and the
    /// error, which is the whole point.
    #[test]
    fn every_exact_count_hq_selection_confirms_for_plutus_anoetic_void_and_sprint() {
        use crate::rules::{legal_actions, PendingDecision};

        let registry = sg_registry();
        let mixed_hq = || -> Vec<CardId> {
            ["hedge_fund", "ice_wall", "offworld_office", "regolith_mining_license", "government_subsidy"]
                .iter()
                .map(|id| CardId(id.to_string()))
                .collect()
        };

        fn combinations(n: usize, k: usize) -> Vec<Vec<usize>> {
            fn go(start: usize, n: usize, k: usize, current: &mut Vec<usize>, out: &mut Vec<Vec<usize>>) {
                if current.len() == k {
                    out.push(current.clone());
                    return;
                }
                for i in start..n {
                    current.push(i);
                    go(i + 1, n, k, current, out);
                    current.pop();
                }
            }
            let mut out = Vec::new();
            go(0, n, k, &mut Vec::new(), &mut out);
            out
        }

        let toggle = |position: usize| PlayerAction::ToggleCardSelection { position };
        let eligible_positions = |state: &GameState| -> Vec<usize> {
            legal_actions(state, &registry)
                .into_iter()
                .filter_map(|a| match a {
                    PlayerAction::ToggleCardSelection { position } => Some(position),
                    _ => None,
                })
                .collect()
        };

        let confirm_every_subset = |label: &str, parked: GameState| {
            let Some(PendingDecision::ChooseCards { min, max, .. }) = &parked.pending_decision else {
                panic!("{label}: expected a parked ChooseCards, got {:?}", parked.pending_decision);
            };
            let (min, max) = (*min as usize, *max as usize);
            assert_eq!(min, max, "{label}: this test is about exact-count prompts");
            let eligible = eligible_positions(&parked);
            assert!(eligible.len() > min, "{label}: the livelock shape needs more eligible cards than `min`, got {eligible:?}");
            assert!(
                !legal_actions(&parked, &registry).contains(&PlayerAction::ConfirmCardSelection),
                "{label}: Confirm must not be offered below `min`"
            );

            let subsets = combinations(eligible.len(), min);
            for subset in &subsets {
                let mut state = parked.clone();
                for &i in subset {
                    state = apply_action(&state, &registry, toggle(eligible[i]))
                        .unwrap_or_else(|e| panic!("{label}: toggling position {} in subset {subset:?} failed: {e:?}", eligible[i]))
                        .0;
                }
                assert!(
                    legal_actions(&state, &registry).contains(&PlayerAction::ConfirmCardSelection),
                    "{label}: Confirm is WITHHELD at a valid count for subset {subset:?} — the prompt is unresolvable there"
                );
                let resolved = apply_action(&state, &registry, PlayerAction::ConfirmCardSelection)
                    .unwrap_or_else(|e| panic!("{label}: Confirm FAILED for subset {subset:?}: {e:?}"))
                    .0;
                assert!(resolved.pending_decision.is_none(), "{label}: Confirm left a decision parked for {subset:?}");
            }

            // A deselect mid-way must not poison the eventual confirm.
            let mut state = parked.clone();
            for &position in &eligible[..min] {
                state = apply_action(&state, &registry, toggle(position)).expect("select").0;
            }
            state = apply_action(&state, &registry, toggle(eligible[0])).expect("deselect the first").0;
            assert!(!legal_actions(&state, &registry).contains(&PlayerAction::ConfirmCardSelection), "{label}: below min again");
            state = apply_action(&state, &registry, toggle(eligible[min])).expect("select a different card").0;
            apply_action(&state, &registry, PlayerAction::ConfirmCardSelection)
                .unwrap_or_else(|e| panic!("{label}: Confirm failed after a deselect/reselect: {e:?}"));

            subsets.len()
        };

        // Plutus's three cards and Anoetic Void's two are costs now, asked
        // one card at a time with no confirm (`payment::Ask::Card`): every
        // sequence of picks has to pay, which is the same demand on the
        // payment that the subsets below make of a prompt.
        fn pay_every_way(label: &str, state: &GameState, registry: &CardRegistry, paid: &dyn Fn(&GameState) -> bool) -> usize {
            let picks: Vec<usize> = legal_actions(state, registry)
                .into_iter()
                .filter_map(|a| match a {
                    PlayerAction::ToggleCardSelection { position } => Some(position),
                    _ => None,
                })
                .collect();
            assert!(!picks.is_empty(), "{label}: a parked payment with nothing to answer it");
            picks
                .into_iter()
                .map(|position| {
                    let (next, _) = apply_action(state, registry, PlayerAction::ToggleCardSelection { position })
                        .unwrap_or_else(|e| panic!("{label}: picking {position} failed: {e:?}"));
                    if next.pending_payment.is_some() {
                        pay_every_way(label, &next, registry, paid)
                    } else {
                        assert!(paid(&next), "{label}: the picks ending at {position} did not pay");
                        1
                    }
                })
                .sum()
        }

        // Plutus: 3 of 5 as an alternative rez cost (its only available way
        // to pay here — no agenda to forfeit — so no alternative is asked).
        let mut plutus = base_state();
        plutus.corp.installed = vec![corp_root("plutus", ServerId::Remote(0))];
        plutus.corp.installed[0].rezzed = false;
        plutus.corp.hq = mixed_hq();
        let (plutus, _) = apply_action(&plutus, &registry, PlayerAction::RezIce { ice: install_of(&plutus, "plutus") })
            .expect("rez via the trash-three alternative");
        assert_eq!(pay_every_way("plutus", &plutus, &registry, &|s| s.corp.installed[0].rezzed && s.corp.hq.len() == 2), 60, "5 × 4 × 3");

        // Anoetic Void: 2 of 5 behind the paid choice on approach.
        let mut void = base_state();
        void.phase = GamePhase::Action(Side::Runner);
        void.runner.resources.clicks = Clicks(4);
        void.corp.resources.credits = Credits(5);
        void.corp.hq = mixed_hq();
        void.corp.installed = vec![crate::rules::InstalledCard {
            install_id: InstallId(1030),
            card: CardId("anoetic_void".to_string()),
            server: ServerId::Remote(0),
            rezzed: true,
            ..Default::default()
        }];
        let (void, _) = apply_action(&void, &registry, PlayerAction::InitiateRun { server: ServerId::Remote(0) }).expect("run");
        let (void, _) = crate::rules::test_support::through_movement(&void, &registry).expect("approach");
        let (void, _) = apply_action(&void, &registry, PlayerAction::AcceptPendingPaidChoice { cost_option_index: None })
            .expect("pay 2");
        assert_eq!(pay_every_way("anoetic_void", &void, &registry, &|s| s.active_run.is_none() && s.corp.hq.len() == 3), 20, "5 × 4");

        // Sprint: draw 3 into a 4-card hand, then shuffle exactly 2 of the 7 back.
        let mut sprint = base_state();
        sprint.corp.hq = mixed_hq();
        sprint.corp.hq[0] = CardId("sprint".to_string());
        sprint.corp.r_and_d = vec![CardId("tithe".to_string()), CardId("palisade".to_string()), CardId("seamless_launch".to_string())];
        let (sprint, _) = apply_action(&sprint, &registry, PlayerAction::PlayOperation { card_id: CardId("sprint".to_string()) })
            .expect("play sprint");
        assert_eq!(sprint.corp.hq.len(), 7, "4 kept + 3 drawn");
        assert_eq!(confirm_every_subset("sprint", sprint), 21);
    }

    /// Every `PromptChooseCards` in the pool, read straight off the card
    /// JSON: `min <= max` always, and the `min > 0` prompts — the ones a
    /// chooser *must* satisfy before Confirm is legal, i.e. every prompt
    /// that can livelock a chooser that deselects — listed by card and zone
    /// in the test output so the set of must-resolve prompts is one command
    /// away (`cargo test -p netrunner_core every_prompt -- --nocapture`).
    /// The engine already refuses to park a prompt with fewer than `min`
    /// eligible cards; this is the authoring-time half of that guard.
    #[test]
    fn every_prompt_in_the_pool_has_min_at_most_max_and_the_must_resolve_ones_are_listed() {
        fn walk(value: &serde_json::Value, card: &str, path: &str, found: &mut Vec<(String, String, u64, u64, String)>) {
            match value {
                serde_json::Value::Object(map) => {
                    if let Some(serde_json::Value::Object(prompt)) = map.get("PromptChooseCards") {
                        let n = |key: &str| prompt.get(key).and_then(|v| v.as_u64());
                        let (min, max) = (n("min").unwrap_or(0), n("max").unwrap_or(0));
                        let zone = prompt.get("source").map_or("?".to_string(), |z| z.to_string());
                        found.push((card.to_string(), path.to_string(), min, max, zone));
                    }
                    for (key, child) in map {
                        walk(child, card, &format!("{path}/{key}"), found);
                    }
                }
                serde_json::Value::Array(items) => {
                    for (index, child) in items.iter().enumerate() {
                        walk(child, card, &format!("{path}[{index}]"), found);
                    }
                }
                _ => {}
            }
        }

        let data = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("data");
        let mut found = Vec::new();
        for side in ["corp", "runner"] {
            let mut files: Vec<_> = std::fs::read_dir(data.join(side)).expect("card data dir").flatten().collect();
            files.sort_by_key(|entry| entry.path());
            for entry in files {
                let path = entry.path();
                if path.extension().is_some_and(|e| e == "json") {
                    let text = std::fs::read_to_string(&path).expect("card JSON is readable");
                    let value: serde_json::Value = serde_json::from_str(&text).expect("card JSON parses");
                    let card = value.get("id").and_then(|v| v.as_str()).unwrap_or("?").to_string();
                    walk(&value, &card, "", &mut found);
                }
            }
        }
        assert!(found.len() > 40, "the pool has many prompts; found {}", found.len());

        for (card, path, min, max, _) in &found {
            assert!(min <= max, "{card}{path}: PromptChooseCards min {min} > max {max} can never be confirmed");
        }
        let must_resolve: Vec<_> = found.iter().filter(|(_, _, min, _, _)| *min > 0).collect();
        println!("{} PromptChooseCards in the pool, {} with min > 0 (must be satisfied before Confirm):", found.len(), must_resolve.len());
        for (card, path, min, max, zone) in &must_resolve {
            println!("  {card:36} min {min} max {max}  from {zone}  at {path}");
        }
    }

    #[test]
    fn lamplighter_taxes_a_tag_or_three_credits_and_burns_out_when_its_server_gives_up_an_agenda() {
        let registry = sg_registry();
        let mut state = runner_turn(5, 4);
        state.corp.installed = vec![
            ice_installed("lamplighter", ServerId::Remote(0), true),
            corp_root("offworld_office", ServerId::Remote(0)),
        ];
        state.corp.installed[1].rezzed = false;

        let (state, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Remote(0) }).expect("run");
        let (state, _) = crate::rules::test_support::continue_run(&state, &registry).expect("approach");
        let state = advance_until_choice(state, &registry);
        assert!(matches!(state.pending_paid_choice.as_ref().map(|p| p.side), Some(Side::Runner)), "pay 3 or take the tag");

        // Paying keeps the Runner clean, and the second subroutine then
        // finds them untagged and lets the run continue.
        let (paid, _) = apply_action(&state, &registry, PlayerAction::AcceptPendingPaidChoice { cost_option_index: None }).expect("pay 3");
        assert_eq!(paid.runner.resources.credits, Credits(2), "5 less the 3 it cost to dodge the tag");
        assert_eq!(paid.runner.tags, 0);
        let (paid, _) = pass_until_settled(paid, &registry);
        assert!(paid.active_run.is_some(), "an untagged Runner walks past subroutine 2");

        // Refusing takes the tag, and then the run ends.
        let (tagged, _) = apply_action(&state, &registry, PlayerAction::DeclinePendingPaidChoice).expect("refuse");
        assert_eq!(tagged.runner.tags, 1);
        let (tagged, _) = pass_until_settled(tagged, &registry);
        assert!(tagged.active_run.is_none(), "end the run if the Runner is tagged");

        // Stealing an agenda from the server it protects burns it out.
        let (state, _) = pass_until_settled(paid, &registry);
        let state = advance_until_choice(state, &registry);
        let (state, _) = apply_action(&state, &registry, PlayerAction::StealAgenda { card_id: CardId("offworld_office".to_string()) }).expect("steal");
        assert!(!state.corp.installed.iter().any(|c| c.card.0 == "lamplighter"), "trashed itself");
        assert!(state.corp.archives.iter().any(|a| a.card.0 == "lamplighter"));
    }


    // ---- Elevation Stage 9: Hidden Funds, Peculiarity ----

    #[test]
    fn pt_untaian_pays_one_to_advance_an_unrezzed_card_when_hq_is_down_to_three() {
        let registry = sg_registry();
        let base = || {
            let mut state = base_state();
            state.corp.identity = Some(CardId("pt_untaian_lifes_building_blocks".to_string()));
            state.corp.r_and_d = vec![CardId("hedge_fund".to_string()); 4];
            state.corp.resources.credits = Credits(1);
            state.corp.installed = vec![
                corp_root("offworld_office", ServerId::Remote(0)),
                corp_root("pad_campaign", ServerId::Remote(1)),
                corp_root("nico_campaign", ServerId::Remote(2)),
            ];
            state.corp.installed[0].rezzed = false;
            state.corp.installed[1].rezzed = false;
            state
        };

        // Four cards in HQ closes the offer.
        let mut full = base();
        full.corp.hq = vec![CardId("hedge_fund".to_string()); 4];
        let (full, _) = apply_action(&crate::rules::test_support::clicks_spent(&full), &registry, PlayerAction::EndTurn).expect("end the corp turn");
        let full = advance_until_choice(full, &registry);
        assert!(full.pending_paid_choice.is_none(), "four in HQ is too many");

        // Three opens it.
        let mut state = base();
        state.corp.hq = vec![CardId("hedge_fund".to_string()); 3];
        let (state, _) = apply_action(&crate::rules::test_support::clicks_spent(&state), &registry, PlayerAction::EndTurn).expect("end the corp turn");
        let state = advance_until_choice(state, &registry);
        assert!(state.pending_paid_choice.is_some(), "three or fewer opens it");
        let (state, _) = apply_action(&state, &registry, PlayerAction::AcceptPendingPaidChoice { cost_option_index: None }).expect("pay 1");
        assert_eq!(state.corp.resources.credits, Credits(0));
        // A rezzed asset is not "an unrezzed card you can advance", and
        // neither is an unrezzed one with no advancement requirement.
        assert!(apply_action(&state, &registry, PlayerAction::ToggleCardSelection { position: position_of(&state, "nico_campaign") }).is_err(), "rezzed");
        assert!(apply_action(&state, &registry, PlayerAction::ToggleCardSelection { position: position_of(&state, "pad_campaign") }).is_err(), "not advanceable");
        let (state, _) = apply_action(&state, &registry, PlayerAction::ToggleCardSelection { position: position_of(&state, "offworld_office") }).expect("the agenda");
        let (state, _) = apply_action(&state, &registry, PlayerAction::ConfirmCardSelection).expect("advance it");
        let agenda = state.corp.installed.iter().find(|c| c.card.0 == "offworld_office").expect("still there");
        assert_eq!(agenda.advancement_tokens, 1);
    }

    #[test]
    fn proprionegation_scores_with_a_counter_that_sends_the_runner_back_to_archives() {
        let registry = sg_registry();
        let mut state = base_state();
        state.corp.installed = vec![corp_root("proprionegation", ServerId::Remote(0))];
        state.corp.installed[0].rezzed = false;
        state.corp.installed[0].advancement_tokens = 4;

        let (state, _) = apply_action(&state, &registry, PlayerAction::ScoreAgenda { target: install_of(&state, "proprionegation") }).expect("score");
        assert_eq!(state.corp.scored_agendas[0].agenda_counters, 1, "a counter on scoring");
        let ability = PlayerAction::ActivateAbility { target: state.corp.scored_agendas[0].install_id, ability_index: 0 };
        // Outside a run there is nothing to move, so it is never offered.
        let (state, _) = close_all_windows(state, &registry);
        assert!(!crate::rules::legal_actions(&state, &registry).contains(&ability));

        // Mid-run it moves the Runner to the outermost position of Archives.
        let mut state = state;
        state.phase = crate::rules::GamePhase::Action(Side::Runner);
        state.runner.resources.clicks = Clicks(4);
        state.corp.installed = vec![
            ice_installed("ice_wall", ServerId::Hq, true),
            ice_installed("enigma", ServerId::Archives, false),
        ];
        let (state, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Hq }).expect("run HQ");
        let (state, _) = crate::rules::test_support::continue_run(&state, &registry).expect("approach Ice Wall");
        let (state, _) = apply_action(&state, &registry, PlayerAction::PassPriority { side: Side::Runner }).expect("runner passes first");
        let (state, events) = apply_action(&state, &registry, ability).expect("spend the counter");
        assert!(events.iter().any(|e| matches!(e, crate::rules::GameEvent::RunRedirected { to: ServerId::Archives, .. })));
        let run = state.active_run.as_ref().expect("still running");
        assert_eq!((run.server, run.position, run.ice.len()), (ServerId::Archives, 0, 1), "outermost, nothing passed");
        assert_eq!(state.corp.scored_agendas[0].agenda_counters, 0);
        // And only once: the counter is gone.
        let again = PlayerAction::ActivateAbility { target: state.corp.scored_agendas[0].install_id, ability_index: 0 };
        assert!(!crate::rules::legal_actions(&state, &registry).contains(&again));
    }

    /// Rules Audit item 7. An iceless server was approached in the action
    /// that began the run, so an unrezzed Anoetic Void never had a window
    /// to be rezzed in before `OnApproachServer` passed it by. The movement
    /// phase (CR 6.9.4d) is that window.
    #[test]
    fn the_corp_may_rez_an_upgrade_in_movement_before_the_server_is_approached() {
        let registry = sg_registry();
        let mut state = runner_turn(5, 4);
        state.corp.resources.credits = Credits(10);
        state.corp.hq = vec![CardId("hedge_fund".to_string()), CardId("government_subsidy".to_string())];
        state.corp.installed = vec![corp_root("anoetic_void", ServerId::Remote(0))];
        state.corp.installed[0].rezzed = false;
        let void = install_of(&state, "anoetic_void");

        let (state, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Remote(0) }).expect("run");
        let (state, events) = crate::rules::test_support::continue_run(&state, &registry).expect("into movement");
        assert!(!events.iter().any(|e| matches!(e, crate::rules::GameEvent::ServerApproached { .. })), "{events:?}");
        assert_eq!(state.active_run.as_ref().unwrap().phase, crate::rules::RunPhase::Movement);
        assert!(state.paid_ability_window.is_none(), "the jack-out decision is the Runner's alone");
        assert!(crate::rules::legal_actions(&state, &registry).contains(&PlayerAction::JackOut));

        let (state, _) = crate::rules::test_support::continue_run(&state, &registry).expect("go on");
        assert!(state.paid_ability_window.is_some(), "movement's window");
        assert!(!crate::rules::legal_actions(&state, &registry).contains(&PlayerAction::JackOut), "the door is shut");
        let (state, _) = apply_action(&state, &registry, PlayerAction::PassPriority { side: Side::Runner }).expect("runner passes");
        assert!(crate::rules::legal_actions(&state, &registry).contains(&PlayerAction::RezIce { ice: void }));
        let (state, _) = apply_action(&state, &registry, PlayerAction::RezIce { ice: void }).expect("rez the Void");
        let (state, events) = pass_until_settled(state, &registry);
        assert!(events.contains(&crate::rules::GameEvent::ServerApproached { server: ServerId::Remote(0) }));
        assert!(state.pending_paid_choice.is_some(), "the Void, rezzed in time, asks as the server is approached");
    }

    /// Rules Audit item 7. Passing a piece of ice used to *be* approaching
    /// the next, jack-out open, so the Runner watched the Corp rez in the
    /// approach window and then left. The decision is movement's, before
    /// the window and before the approach.
    #[test]
    fn the_runner_decides_to_jack_out_before_the_corp_can_rez_the_next_ice() {
        let registry = sg_registry();
        let mut state = runner_turn(5, 4);
        state.corp.resources.credits = Credits(10);
        state.corp.installed =
            vec![ice_installed("ice_wall", ServerId::Hq, false), ice_installed("enigma", ServerId::Hq, false)];
        let enigma = install_of(&state, "enigma");

        let (state, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Hq }).expect("run");
        let (state, _) = crate::rules::test_support::continue_run(&state, &registry).expect("approach Ice Wall");
        let (state, _) = close_all_windows(state, &registry);
        let run = state.active_run.as_ref().unwrap();
        assert_eq!((run.phase, run.position), (crate::rules::RunPhase::Movement, 1), "Ice Wall passed unrezzed");
        let legal = crate::rules::legal_actions(&state, &registry);
        assert!(legal.contains(&PlayerAction::JackOut));
        assert!(!legal.contains(&PlayerAction::RezIce { ice: enigma }), "nothing to rez until it is approached");

        let (state, _) = crate::rules::test_support::through_movement(&state, &registry).expect("go on");
        let run = state.active_run.as_ref().unwrap();
        assert_eq!((run.phase, run.position), (crate::rules::RunPhase::ApproachIce, 1));
        let legal = crate::rules::legal_actions(&state, &registry);
        assert!(legal.contains(&PlayerAction::RezIce { ice: enigma }), "Enigma's rez window");
        let (state, _) = apply_action(&state, &registry, PlayerAction::RezIce { ice: enigma }).expect("rez Enigma");
        assert_eq!(
            apply_action(&state, &registry, PlayerAction::JackOut).err(),
            Some(crate::rules::RulesError::IllegalJackOutWindow { phase: crate::rules::RunPhase::ApproachIce }),
            "having seen the rez, the Runner cannot leave"
        );
    }

