        let (state, _) = apply_action(&state, &registry, PlayerAction::TrashAccessedCard { card_id: id("tucana") }).expect("trash it");
        let (state, _) = close_all_windows(state, &registry);
        assert!(state.find_corp_install(InstallId(90)).is_none());
