    // ---- Stage 5b: Archives ----

    /// "Install 1 **facedown** card from Archives": only a facedown card is
    /// offered, and the install takes the copy chosen — the faceup Ice Wall
    /// beside the facedown one stays where the Runner can see it.
    #[test]
    fn hybrid_release_installs_a_facedown_card_from_archives_when_scored() {
        let registry = registry();
        let mut state = base_state();
        state.corp.resources.credits = Credits(5);
        state.corp.installed = vec![agenda_at("hybrid_release", 2)];
        state.corp.archives = vec![
            crate::rules::ArchivedCard::faceup(id("ice_wall")),
            crate::rules::ArchivedCard::facedown(id("ice_wall")),
            crate::rules::ArchivedCard::faceup(id("pad_campaign")),
        ];
        let scored = score(&state, &registry, "hybrid_release").expect("score it");
        assert_eq!(toggles(&scored, &registry), vec![1], "the facedown card alone");
        let (asked, _) = pick(&scored, &registry, 1);
        assert!(matches!(asked.pending_decision, Some(PendingDecision::ChooseServer { .. })), "where to install it");
        let (installed, _) = apply_action(&asked, &registry, PlayerAction::ChooseServerForPendingDecision { server: ServerId::Hq }).expect("protect HQ");
        let ice = installed.corp.installed.iter().find(|card| card.card == id("ice_wall")).expect("Ice Wall installed");
        assert!(!ice.rezzed, "installed facedown");
        assert_eq!(installed.corp.archives.len(), 2);
        assert!(installed.corp.archives.iter().all(|archived| !archived.facedown), "the facedown copy went, the faceup one stayed");

        // Declined, and nothing to install: no question at all.
        let (declined, _) = apply_action(&scored, &registry, PlayerAction::ConfirmCardSelection).expect("decline");
        assert!(declined.pending_decision.is_none());
        assert_eq!(declined.corp.archives.len(), 3);
        state.corp.archives.retain(|archived| !archived.facedown);
        assert!(score(&state, &registry, "hybrid_release").expect("score it").pending_decision.is_none());
    }

    /// "Whenever the Runner approaches this server, you may turn 1 facedown
    /// piece of ice in Archives faceup. If you do, resolve 1 subroutine on
    /// that ice."
    #[test]
    fn nanisivik_grid_turns_a_facedown_ice_in_archives_faceup_and_resolves_its_subroutine() {
        let registry = registry();
        let mut state = runner_turn();
        state.corp.installed = vec![rezzed_root_at("nanisivik_grid", 0)];
        state.corp.archives = vec![crate::rules::ArchivedCard::facedown(id("hedge_fund")), crate::rules::ArchivedCard::facedown(id("ice_wall"))];
        let (running, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Remote(0) }).expect("initiate run");
        let (approached, _) = crate::rules::test_support::through_movement(&running, &registry).expect("approach the server");
        assert_eq!(toggles(&approached, &registry), vec![1], "facedown ice alone");
        let (ended, events) = pick(&approached, &registry, 1);
        assert!(ended.active_run.is_none(), "Ice Wall's \"End the run.\"");
        assert!(!ended.corp.archives[1].facedown, "turned faceup");
        assert!(ended.corp.archives[0].facedown);
        assert!(events.iter().any(|event| matches!(event, GameEvent::ArchivesTurnedFaceup { count: 1 })));

        // Two subroutines are a choice, worded as the ice prints them.
        state.corp.archives = vec![crate::rules::ArchivedCard::facedown(id("enigma"))];
        let (running, _) = apply_action(&state, &registry, PlayerAction::InitiateRun { server: ServerId::Remote(0) }).expect("initiate run");
        let (approached, _) = crate::rules::test_support::through_movement(&running, &registry).expect("approach the server");
        let (asked, _) = pick(&approached, &registry, 0);
        let Some(PendingDecision::ChooseEffect { option_texts: texts, .. }) = &asked.pending_decision else { panic!("a choice: {:?}", asked.pending_decision) };
        assert_eq!(texts, &vec!["The Runner loses 1 click.".to_string(), "End the run.".to_string()]);
        let clicks = asked.runner.resources.clicks;
        let (lost, _) = choose(&asked, &registry, 0);
        assert_eq!(lost.runner.resources.clicks.0, clicks.0 - 1);
        assert!(lost.active_run.is_some(), "the run goes on");

        // Declined: Archives untouched.
        let (declined, _) = apply_action(&approached, &registry, PlayerAction::ConfirmCardSelection).expect("decline");
        assert!(declined.corp.archives[0].facedown);
    }


    // ---- Stage 5c: trashes ----

    /// A Runner event whose text trashes an installed Corp card, so the
    /// trash is the Runner's and not an access's.
    fn registry_with_a_trashing_event() -> CardRegistry {
        let mut registry = registry();
        registry.insert(
            serde_json::from_str(
                r#"{"id": "a_trashing_event", "title": "A Trashing Event", "side": "Runner", "card_type": "Event", "cost": 0,
                    "triggers": [{"trigger": "OnPlay", "subject": "This", "effects": [{"PromptChooseCards": {
                        "side": "Runner", "source": "OpponentInstalled", "filter": "Any", "min": 1, "max": 1,
                        "reveal": false, "shuffle_after": false, "destination": "OpponentDiscard"}}]}]}"#,
            )
            .expect("a card file"),
        );
        registry
    }

    /// The Runner plays the trashing event on the Corp install `install`.
    fn trash_by_text(state: &GameState, registry: &CardRegistry, install: u32) -> GameState {
        let mut state = state.clone();
        state.runner.grip.push(id("a_trashing_event"));
        let (asked, _) = apply_action(&state, registry, PlayerAction::PlayEvent { card_id: id("a_trashing_event") }).expect("play");
        let position = asked.corp.installed.iter().position(|card| card.install_id == InstallId(install)).expect("installed");
        let (chose, _) = apply_action(&asked, registry, PlayerAction::ToggleCardSelection { position }).expect("select");
        close_all_windows(apply_action(&chose, registry, PlayerAction::ConfirmCardSelection).expect("trash it").0, registry).0
    }

    #[test]
    fn hostile_architecture_hears_its_own_trash_by_the_runners_text_while_it_was_rezzed() {
        let registry = registry_with_a_trashing_event();
        let mut state = runner_turn();
        state.runner.grip = vec![id("sure_gamble"); 4];
        state.corp.installed = vec![at("hostile_architecture", 80, 0, true)];
        assert_eq!(trash_by_text(&state, &registry, 80).runner.grip.len(), 2, "including this asset: 2 meat damage");
        state.corp.installed[0].rezzed = false;
        assert_eq!(trash_by_text(&state, &registry, 80).runner.grip.len(), 4, "never active, so nothing heard");
    }

    #[test]
    fn yakov_gains_two_for_each_trash_from_its_server_its_own_included() {
        let registry = registry_with_a_trashing_event();
        let mut state = runner_turn();
        state.runner.resources.credits = Credits(20);
        state.corp.resources.credits = Credits(0);
        let mut ice = ice_at("ice_wall", ServerId::Remote(0), true);
        ice.install_id = InstallId(83);
        state.corp.installed = vec![at("yakov_erikovich_avdakov", 80, 0, true), at("pad_campaign", 81, 0, false), at("pad_campaign", 82, 1, false), ice];
        let gained = |state: &GameState| state.corp.resources.credits.0;
        assert_eq!(gained(&trash_by_text(&state, &registry, 81)), 2, "from the root of this server");
        assert_eq!(gained(&trash_by_text(&state, &registry, 83)), 2, "protecting it");
        assert_eq!(gained(&trash_by_text(&state, &registry, 82)), 0, "another server");
        assert_eq!(gained(&trash_by_text(&state, &registry, 80)), 2, "including this upgrade");
        let mut unprotected = state.clone();
        unprotected.corp.installed.pop();
        let (accessing, _) = run_to_completion(close_all_windows(unprotected, &registry).0, &registry, ServerId::Remote(0));
        let pad = PlayerAction::SelectCardToAccess { candidate: crate::rules::AccessCandidate::Root(InstallId(81)) };
        let (at_pad, _) = apply_action(&accessing, &registry, pad).expect("access PAD Campaign first");
        let (trashed, _) = apply_action(&at_pad, &registry, PlayerAction::TrashAccessedCard { card_id: id("pad_campaign") }).expect("trash it");
        assert_eq!(gained(&trashed), 2, "the Runner's trash on access");

        // Unrezzed, it is not active and hears nothing.
        state.corp.installed[0].rezzed = false;
        assert_eq!(gained(&trash_by_text(&state, &registry, 81)), 0);
        assert_eq!(gained(&trash_by_text(&state, &registry, 80)), 0);
    }

    /// "Except during installation": a second region installed in its
    /// server trashes the first (CR 8.5.6), and nothing is gained.
    #[test]
    fn yakov_gains_nothing_for_a_trash_made_by_installing() {
        let registry = registry();
        let mut state = base_state();
        state.corp.resources.credits = Credits(0);
        state.corp.installed = vec![at("yakov_erikovich_avdakov", 80, 0, true), at("nanisivik_grid", 81, 0, false)];
        state.corp.hq = vec![id("nanisivik_grid")];
        let install = PlayerAction::InstallCard { card_id: id("nanisivik_grid"), zone: ServerId::Remote(0), slot: InstallSlot::Root, trash_first: false };
        let (installed, _) = apply_action(&state, &registry, install).expect("install a second region");
        assert_eq!(installed.corp.installed.iter().filter(|card| card.card == id("nanisivik_grid")).count(), 1, "the first region is trashed");
        assert_eq!(installed.corp.resources.credits, Credits(0));
    }

    #[test]
    fn kimberlite_field_trashes_a_runner_card_no_dearer_than_the_rezzed_card_the_corp_trashed() {
        let registry = registry();
        let mut state = base_state();
        state.corp.installed = vec![agenda_at("kimberlite_field", 4), at("pad_campaign", 81, 1, true)];
        state.runner.rig = vec![rig_card("mayfly", 90), rig_card("carmen", 91)];
        let scored = score(&state, &registry, "kimberlite_field").expect("score it");
        assert!(scored.pending_paid_choice.as_ref().is_some_and(|choice| choice.side == Side::Corp), "you may trash 1 of your rezzed cards");
        let (declined, _) = apply_action(&scored, &registry, PlayerAction::DeclinePendingPaidChoice).expect("decline");
        assert_eq!((declined.corp.installed.len(), declined.runner.rig.len()), (1, 2));

        let (paid, _) = apply_action(&scored, &registry, accept()).expect("trash PAD Campaign");
        assert!(paid.corp.installed.is_empty(), "PAD Campaign trashed");
        assert_eq!(toggles(&paid, &registry), vec![0], "Mayfly (1[credit]) and not Carmen (5[credit]): PAD Campaign's rez cost is 2[credit]");
        let (trashed, _) = pick(&paid, &registry, 0);
        assert_eq!(trashed.runner.rig.iter().map(|card| card.card.clone()).collect::<Vec<_>>(), vec![id("carmen")]);
        assert!(trashed.runner.heap.contains(&id("mayfly")));

        // Nothing rezzed to trash: no offer to pay.
        state.corp.installed[1].rezzed = false;
        let unpaid = score(&state, &registry, "kimberlite_field").expect("score it");
        assert!(apply_action(&unpaid, &registry, accept()).is_err(), "nothing rezzed to trash");
    }

    #[test]
    fn world_tree_trades_another_install_for_one_of_its_type_from_the_stack_three_credits_cheaper() {
        let registry = registry();
        let mut state = runner_turn();
        state.runner.resources.credits = Credits(3);
        state.runner.rig = vec![rig_card("world_tree", 90), rig_card("smartware_distributor", 91)];
        state.runner.stack = vec![id("sure_gamble"), id("red_team"), id("sure_gamble")];
        let (asked, _) = run_to_completion(state.clone(), &registry, ServerId::Hq);
        assert!(asked.pending_paid_choice.as_ref().is_some_and(|choice| choice.side == Side::Runner), "the first successful run");
        let (searching, _) = apply_action(&asked, &registry, accept()).expect("trash Smartware Distributor");
        assert!(searching.runner.heap.contains(&id("smartware_distributor")));
        let resources: Vec<usize> = crate::rules::legal_actions_for(&searching, &registry, Side::Runner)
            .into_iter()
            .filter_map(|action| match action {
                PlayerAction::ToggleCardSelection { position } => Some(position),
                _ => None,
            })
            .collect();
        assert_eq!(resources.len(), 1, "a resource, as the card trashed was");
        let (chose, _) = apply_action(&searching, &registry, PlayerAction::ToggleCardSelection { position: resources[0] }).expect("Red Team");
        let (installed, _) = apply_action(&chose, &registry, PlayerAction::ConfirmCardSelection).expect("install it");
        assert!(installed.runner.rig.iter().any(|card| card.card == id("red_team")), "installed");
        assert_eq!(installed.runner.resources.credits, Credits(3 - (5 - 3)), "Red Team's 5[credit], paying 3[credit] less");
        assert_eq!(installed.runner.stack.len(), 2);

        // The second successful run this turn asks nothing.
        let (again, _) = run_to_completion(close_all_windows(installed, &registry).0, &registry, ServerId::Hq);
        assert!(again.pending_paid_choice.is_none());
    }


    // ---- Stage 5d: the stack and HQ ----

    fn runner_toggles(state: &GameState, registry: &CardRegistry) -> Vec<usize> {
        crate::rules::legal_actions_for(state, registry, Side::Runner)
            .into_iter()
            .filter_map(|action| match action {
                PlayerAction::ToggleCardSelection { position } => Some(position),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn reprise_plays_after_a_steal_adds_an_install_to_hq_and_may_run() {
        let registry = registry_with_a_plain_agenda();
        let mut state = runner_turn();
        state.runner.resources.credits = Credits(10);
        state.runner.grip = vec![id("reprise")];
        state.corp.installed = vec![root_at("a_plain_agenda", 0), at("pad_campaign", 81, 1, false)];
        let play = PlayerAction::PlayEvent { card_id: id("reprise") };
        assert!(apply_action(&state, &registry, play.clone()).is_err(), "play only if you stole an agenda this turn");

        let (accessed, _) = run_to_completion(state, &registry, ServerId::Remote(0));
        let (stolen, _) = apply_action(&accessed, &registry, PlayerAction::StealAgenda { card_id: id("a_plain_agenda") }).expect("steal");
        let (asked, _) = apply_action(&close_all_windows(stolen, &registry).0, &registry, play).expect("play Reprise");
        assert_eq!(runner_toggles(&asked, &registry), vec![0], "PAD Campaign, the one install left");
        let (chose, _) = apply_action(&asked, &registry, PlayerAction::ToggleCardSelection { position: 0 }).expect("select");
        let (offered, _) = apply_action(&chose, &registry, PlayerAction::ConfirmCardSelection).expect("add it to HQ");
        assert!(offered.corp.installed.is_empty());
        assert!(offered.corp.hq.contains(&id("pad_campaign")));
        assert_eq!(options(&offered), Some(2), "you may run any server");
        let (choosing, _) = choose(&offered, &registry, 0);
        let (running, _) = apply_action(&choosing, &registry, PlayerAction::ChooseServerForPendingDecision { server: ServerId::Hq }).expect("run HQ");
        assert_eq!(running.active_run.as_ref().and_then(|run| run.initiated_by.clone()), Some(id("reprise")));
    }

    #[test]
    fn concerto_reveals_the_top_card_into_the_grip_and_runs_with_its_cost_in_credits() {
        let registry = registry();
        let mut state = runner_turn();
        state.runner.grip = vec![id("concerto")];
        state.runner.stack = vec![id("mayfly"), id("sure_gamble")];
        let (asked, _) = apply_action(&state, &registry, PlayerAction::PlayEvent { card_id: id("concerto") }).expect("play Concerto");
        assert_eq!(runner_toggles(&asked, &registry), vec![0], "the top card, the zone's one card");
        let (chose, _) = apply_action(&asked, &registry, PlayerAction::ToggleCardSelection { position: 0 }).expect("select");
        let (revealed, events) = apply_action(&chose, &registry, PlayerAction::ConfirmCardSelection).expect("reveal it");
        assert!(events.iter().any(|event| matches!(event, GameEvent::CardsSelected { revealed: true, .. })), "revealed");
        assert_eq!(revealed.runner.grip, vec![id("sure_gamble")]);
        let (running, _) = apply_action(&revealed, &registry, PlayerAction::ChooseServerForPendingDecision { server: ServerId::Hq }).expect("run HQ");
        let run = running.active_run.as_ref().expect("a run");
        assert_eq!(run.bonus_run_credits, 5, "Sure Gamble's printed play cost");
        assert_eq!(run.initiated_by, Some(id("concerto")), "the run is Concerto's, not the revealed card's");

        // An empty stack reveals nothing and still runs.
        state.runner.stack.clear();
        let (choosing, _) = apply_action(&state, &registry, PlayerAction::PlayEvent { card_id: id("concerto") }).expect("play Concerto");
        let (running, _) = apply_action(&choosing, &registry, PlayerAction::ChooseServerForPendingDecision { server: ServerId::Hq }).expect("run HQ");
        assert_eq!(running.active_run.as_ref().map(|run| run.bonus_run_credits), Some(0));
        assert!(running.pending_decision.is_none());
    }

    #[test]
    fn asmund_pudlat_hosts_two_different_viruses_and_hands_one_over_each_turn_until_empty() {
        let registry = registry();
        let mut state = runner_turn();
        state.runner.resources.credits = Credits(5);
        state.runner.grip = vec![id("asmund_pudlat")];
        state.runner.stack = vec![id("leech"), id("sure_gamble"), id("leech"), id("botulus")];
        let (asked, _) = apply_action(&state, &registry, PlayerAction::InstallResource { card_id: id("asmund_pudlat"), host: None }).expect("install");
        assert_eq!(runner_toggles(&asked, &registry), vec![0, 2, 3], "virus or weapon cards");
        let (one, _) = apply_action(&asked, &registry, PlayerAction::ToggleCardSelection { position: 0 }).expect("a Leech");
        assert_eq!(runner_toggles(&one, &registry), vec![0, 3], "not a second Leech, and the first may be put back");
        let (two, _) = apply_action(&one, &registry, PlayerAction::ToggleCardSelection { position: 3 }).expect("Botulus");
        let (hosted, _) = apply_action(&two, &registry, PlayerAction::ConfirmCardSelection).expect("host them");
        let asmund = hosted.runner.rig.iter().find(|card| card.card == id("asmund_pudlat")).expect("installed");
        assert_eq!(asmund.hosted_cards, vec![id("leech"), id("botulus")]);
        assert_eq!(hosted.runner.stack.len(), 2, "searched, and shuffled");

        let asked = begin_the_turn_of(hosted, &registry, Side::Runner);
        let (first, _) = apply_action(&asked, &registry, PlayerAction::ToggleCardSelection { position: 0 }).expect("a hosted card");
        let (kept, _) = apply_action(&first, &registry, PlayerAction::ConfirmCardSelection).expect("to the grip");
        assert!(kept.runner.grip.contains(&id("leech")));
        assert!(kept.runner.rig.iter().any(|card| card.card == id("asmund_pudlat")), "one card still hosted");

        let mut next = kept;
        next.phase = GamePhase::Action(Side::Runner);
        let asked = begin_the_turn_of(next, &registry, Side::Runner);
        let (last, _) = apply_action(&asked, &registry, PlayerAction::ToggleCardSelection { position: 0 }).expect("the last hosted card");
        let (emptied, _) = apply_action(&last, &registry, PlayerAction::ConfirmCardSelection).expect("to the grip");
        assert!(emptied.runner.grip.contains(&id("botulus")));
        assert!(!emptied.runner.rig.iter().any(|card| card.card == id("asmund_pudlat")), "no more hosted cards: trashed");
        assert!(emptied.runner.heap.contains(&id("asmund_pudlat")));
    }

    // ---- Stage 6a: charge ----

    /// The counters on the rig card `card`.
    fn counters_on(state: &GameState, card: &str) -> u32 {
        state.runner.rig.iter().find(|installed| installed.card == id(card)).expect("installed").counters
    }

    /// "Charge 1 of your installed cards" (CR 10.10.1): only a card that
    /// already hosts a power counter is offered — Cataloguer with none is
    /// not — and Cleaver breaking two of Brân's subroutines at once is one
    /// first time, not two: the encounter had counted one break when the
    /// first was heard.
    #[test]
    fn flux_capacitor_charges_the_first_time_a_subroutine_on_its_host_is_broken_each_encounter() {
        let registry = registry();
        let mut state = runner_turn();
        state.corp.installed = vec![ice_at_hq("bran_1_0")];
        let flux = crate::rules::InstalledRunnerCard { hosted_on_ice: Some(fixture_install_id("bran_1_0")), ..in_rig("flux_capacitor", 0, 0) };
        state.runner.rig = vec![flux, in_rig("cleaver", 6, 0), in_rig("time_bomb", 0, 1), in_rig("cataloguer", 0, 0)];
        state.runner.resources.credits = Credits(20);
        let at_ice = encounter(&state, &registry);
        let charging = use_ability(&at_ice, &registry, "cleaver", 0).expect("break up to 2 barrier subroutines");
        assert_eq!(broken(&charging), 2);
        assert_eq!(runner_toggles(&charging, &registry), vec![2], "Time Bomb, the one card with a power counter");
        let (charged, _) = pick(&charging, &registry, 2);
        assert_eq!(counters_on(&charged, "time_bomb"), 2);
        assert_eq!(counters_on(&charged, "cataloguer"), 0);
        assert_eq!(charged.active_run.as_ref().map(|run| run.this_encounter.subroutines_broken), Some(2));

        let charged = match charged.paid_ability_window.as_ref().map(|window| window.active_priority) {
            Some(Side::Corp) => apply_action(&charged, &registry, PlayerAction::PassPriority { side: Side::Corp }).expect("the Corp passes back").0,
            _ => charged,
        };
        let again = use_ability(&charged, &registry, "cleaver", 0).expect("break the third");
        assert_eq!(broken(&again), 3);
        assert!(again.pending_decision.is_none(), "not the first break this encounter");
        assert_eq!(counters_on(&again, "time_bomb"), 2);

        // Declined, nothing is charged.
        let (declined, _) = apply_action(&charging, &registry, PlayerAction::ConfirmCardSelection).expect("you may");
        assert_eq!(counters_on(&declined, "time_bomb"), 1);

        // On other ice it hears nothing.
        let mut elsewhere = state;
        elsewhere.corp.installed.push(crate::rules::InstalledCard { server: ServerId::RnD, ..ice_at_hq("ice_wall") });
        elsewhere.runner.rig[0].hosted_on_ice = Some(fixture_install_id("ice_wall"));
        let broke = use_ability(&encounter(&elsewhere, &registry), &registry, "cleaver", 0).expect("break 2");
        assert!(broke.pending_decision.is_none(), "not its host");
    }

    /// The word is the encounter's, and only for what it counts.
    #[test]
    fn a_first_time_each_encounter_is_refused_for_what_the_encounter_does_not_count() {
        let mut card: crate::dsl::CardDefinition = serde_json::from_str(include_str!("../../data/runner/flux_capacitor.json")).expect("the card");
        assert_eq!(card.validate(), Ok(()));
        card.triggers[0].trigger = crate::dsl::Trigger::OnIceFullyBroken;
        assert!(card.validate().is_err(), "the encounter counts subroutines broken");
        card.triggers[0].trigger = crate::dsl::Trigger::OnSubroutineBroken;
        card.triggers[0].first_each_turn = true;
        assert!(card.validate().is_err(), "each turn's or each encounter's, not both");
    }

    #[test]
    fn orca_breaks_every_sentry_subroutine_and_charges_the_first_time_each_turn_it_fully_breaks_ice() {
        let registry = registry();
        let mut state = runner_turn();
        state.corp.installed = vec![ice_at_hq("flywheel"), ice_at_hq("karuna")];
        state.runner.rig = vec![in_rig("orca", 3, 0), in_rig("time_bomb", 0, 1)];
        state.runner.resources.credits = Credits(20);
        let at_ice = encounter(&state, &registry);
        let charging = use_ability(&at_ice, &registry, "orca", 0).expect("2[credit]: break any number of sentry subroutines");
        assert_eq!(broken(&charging), 2, "both, for one payment");
        assert_eq!(charging.runner.resources.credits, Credits(18));
        assert_eq!(runner_toggles(&charging, &registry), vec![1]);
        let (charged, _) = pick(&charging, &registry, 1);
        assert_eq!(counters_on(&charged, "time_bomb"), 2);

        // The second piece of ice, the same turn: fully broken, not charged.
        let first = charged.active_run.as_ref().map(|run| run.position);
        let mut next = charged;
        for _ in 0..12 {
            if next.active_run.as_ref().is_some_and(|run| Some(run.position) != first && run.phase == crate::rules::RunPhase::EncounterIce) {
                break;
            }
            next = match next.paid_ability_window.as_ref().map(|window| window.active_priority) {
                Some(side) => apply_action(&next, &registry, PlayerAction::PassPriority { side }).expect("pass").0,
                None => crate::rules::test_support::continue_run(&next, &registry).expect("on to the next ice").0,
            };
        }
        let next = use_ability(&next, &registry, "orca", 0).expect("break the second");
        assert_eq!(broken(&next), 2);
        assert!(next.pending_decision.is_none(), "not the first time this turn");
        assert_eq!(counters_on(&next, "time_bomb"), 2);

        // A code gate's subroutines are not a sentry's.
        state.corp.installed = vec![ice_at_hq("enigma")];
        assert!(use_ability(&encounter(&state, &registry), &registry, "orca", 0).is_err());
    }

    // ---- Stage 6b: the mark ----

    /// `server` is the Runner's mark for the rest of this turn, as if
    /// identified (CR 10.11.2).
    fn marked(mut state: GameState, server: ServerId) -> GameState {
        state.lingering.push(crate::rules::lingering::LingeringEffect {
            what: crate::rules::lingering::Lingering::Mark(server),
            on: crate::rules::lingering::On::Player(Side::Runner),
            until: crate::rules::lingering::Until::EndOfTurn(state.turn),
            source: id("tunnel_vision"),
        });
        state
    }

    fn identify(state: &mut GameState, registry: &CardRegistry) -> Vec<GameEvent> {
        crate::rules::evaluate_effect(state, &crate::dsl::Effect::IdentifyMark, &mut crate::rules::ResolutionContext::for_card(Some(&id("tunnel_vision"))), registry)
            .expect("identify your mark")
    }

    /// "If you don't have a mark, a random central server becomes your
    /// mark for this turn" (CR 10.11.2), each of the three as likely
    /// (10.11.2a); a mark already there stays (10.11.3), and it is gone
    /// when the turn is (10.11.4).
    #[test]
    fn identifying_the_mark_picks_a_random_central_server_once_a_turn() {
        let registry = registry();
        let mut seen = std::collections::BTreeMap::new();
        for seed in 0..300 {
            let mut state = runner_turn();
            state.seed = seed;
            let events = identify(&mut state, &registry);
            let mark = crate::rules::lingering::mark(&state).expect("a mark");
            assert_eq!(events, vec![GameEvent::MarkIdentified { server: mark }]);
            *seen.entry(format!("{mark:?}")).or_insert(0) += 1;

            let step = state.rng_step;
            assert!(identify(&mut state, &registry).is_empty(), "already identified: nothing");
            assert_eq!((crate::rules::lingering::mark(&state), state.rng_step), (Some(mark), step), "the mark is immutable for the turn");
            state.turn += 1;
            assert_eq!(crate::rules::lingering::mark(&state), None, "a lingering effect that expires at the end of the turn");
        }
        assert_eq!(seen.keys().cloned().collect::<Vec<_>>(), vec!["Archives", "Hq", "RnD"]);
        assert!(seen.values().all(|&count| count > 70), "about a third each: {seen:?}");
    }

